    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Can a C function return a pointer to its own local automatic variable (e.g. return &local_var;)?', 'When a function returns, its stack frame is reclaimed; pointing to reclaimed stack memory is an undefined-behavior bug (dangling pointer).',
    'medium', 1, 0, 49, ARRAY['BCA-103N', 'Unit-4', 'Pointers', 'Dangling-Stack-Pointer']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

