  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the remainder when 2^50 is divided by 7?', 'By Fermat''s Little Theorem or modular cycles: 2^3 = 8 = 1 (mod 7). 50 = 3 * 16 + 2. Thus 2^50 = (2^3)^16 * 2^2 = 1^16 * 4 = 4. Remainder is 4.',
    'medium', 1, 0, 6, ARRAY['BCA-105N', 'Unit-1', 'Modular-Arithmetic', 'Remainder']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

