  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If a quantity increases from 80 to 100, what is the percentage increase?', 'Percentage increase = [(New - Old) / Old] * 100% = [(100 - 80) / 80] * 100% = (20/80) * 100% = 25%.',
    'medium', 1, 0, 19, ARRAY['BCA-105N', 'Unit-1', 'Percentages', 'Percentage-Change']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

