    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If a : b = 2 : 3 and b : c = 4 : 5, what is the combined ratio a : b : c?', 'Multiply first ratio by 4 (8:12) and second ratio by 3 (12:15); combining yields a:b:c = 8 : 12 : 15.',
    'medium', 1, 0, 20, ARRAY['BCA-105N', 'Unit-1', 'Ratios', 'Compounding']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

