  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'According to the Binomial Theorem for a positive integer n, the total number of terms in the expansion of (a + b)^n is:', 'The expansion starts from r = 0 up to r = n, containing exactly n + 1 terms.',
    'easy', 1, 0, 21, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Terms-Count']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

