    (v_q_id, 'n!', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'The symmetry property of binomial coefficients states that nCr is always equal to:', 'Symmetry property: nCr = nC(n-r) because choosing r items to include is equivalent to choosing n-r items to exclude.',
    'easy', 1, 0, 24, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Symmetry']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

