  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the sum of all binomial coefficients in the expansion of (1 + x)^n, i.e., nC0 + nC1 + nC2 + ... + nCn?', 'Substituting x = 1 into (1 + x)^n yields (1 + 1)^n = 2^n = sum of all nCr.',
    'medium', 1, 0, 25, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Sum-of-Coefficients']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
