  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'In the binomial expansion of (a + b)^n, if n is an EVEN integer, how many middle terms exist?', 'When n is even, total terms (n + 1) is odd; hence there is exactly one unique central middle term: T_(n/2 + 1).',
    'medium', 1, 0, 26, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Middle-Term-Even']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
