    (v_q_id, 'Two middle terms', false, 2, now(), now()),
    (v_q_id, 'n middle terms', false, 3, now(), now()),
    (v_q_id, 'No middle terms', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'In the binomial expansion of (a + b)^n, if n is an ODD integer, how many middle terms exist?', 'When n is odd, total terms (n + 1) is even, yielding two middle terms: T_((n+1)/2) and T_((n+3)/2).',
    'medium', 1, 0, 27, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Middle-Term-Odd']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
