  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the 3rd term (T_3) in the expansion of (x + 2)^5?', 'T_3 = T_(2+1) = 5C2 * x^(5-2) * (2)^2 = 10 * x^3 * 4 = 40 x^3.',
    'medium', 1, 0, 28, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Term-Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

