  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the term independent of x (constant term) in the expansion of (x + 1/x)^6?', 'T_(r+1) = 6Cr * x^(6-r) * (x^(-1))^r = 6Cr * x^(6 - 2r). For x^0: 6 - 2r = 0 -> r = 3. T_4 = 6C3 = 20.',
    'medium', 1, 0, 29, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Independent-Term']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

