  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Pascal''s Triangle is a geometric arrangement used to visually determine:', 'Pascal''s Triangle displays binomial coefficients where each number is the sum of the two numbers directly above it: nCr = (n-1)C(r-1) + (n-1)Cr.',
    'easy', 1, 0, 30, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Pascals-Triangle']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

