  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the prime factorization of 360 in canonical exponential form?', '360 = 36 * 10 = (4 * 9) * (2 * 5) = 2^2 * 3^2 * 2 * 5 = 2^3 * 3^2 * 5.',
    'easy', 1, 0, 31, ARRAY['BCA-105N', 'Unit-1', 'Prime-Factorization', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
