  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'How many total positive divisors (factors) does the number 360 possess?', 'Number of divisors for p1^a * p2^b * p3^c is (a+1)(b+1)(c+1) = (3+1)(2+1)(1+1) = 4 * 3 * 2 = 24 divisors.',
    'medium', 1, 0, 32, ARRAY['BCA-105N', 'Unit-1', 'Number-Theory', 'Divisors-Count']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

