  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the greatest number that will divide 43, 91, and 183 so as to leave the same remainder in each case?', 'HCF of differences: |91 - 43| = 48, |183 - 91| = 92, |183 - 43| = 140. HCF(48, 92, 140) = 4.',
    'medium', 1, 0, 33, ARRAY['BCA-105N', 'Unit-1', 'HCF-LCM', 'Word-Problem']::TEXT[], 2024, 'MJPRU BCA Sem 1',
