  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the value of n if nC2 = 21?', 'nC2 = n(n-1)/2 = 21 -> n(n-1) = 42 -> 7 * 6 = 42. Thus n = 7.',
    'medium', 1, 0, 36, ARRAY['BCA-105N', 'Unit-1', 'Combinatorics', 'Equations']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
