    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If nC8 = nC12, what is the value of n?', 'By symmetry nCx = nCy implies x = y or x + y = n. Here 8 + 12 = n -> n = 20.',
    'easy', 1, 0, 37, ARRAY['BCA-105N', 'Unit-1', 'Binomial-Theorem', 'Symmetry']::TEXT[], 2024, 'MJPRU BCA Sem 1',
