  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If the price of a commodity increases by 25%, by what percentage must a family reduce consumption to keep total expenditure constant?', 'Reduction percentage = [r / (100 + r)] * 100 = [25 / 125] * 100 = 20%.',
