  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the sum of an Infinite Geometric Progression (S_infinity) with first term ''a'' and |r| < 1?', 'As n -> infinity, r^n -> 0 (for |r| < 1); hence S_infinity = a / (1 - r).',
    'easy', 1, 0, 15, ARRAY['BCA-105N', 'Unit-2', 'GP', 'Infinite-Sum']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

