    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Calculate the sum of the infinite series: 1 + 1/2 + 1/4 + 1/8 + ...:', 'Here a = 1, r = 1/2 < 1. S_infinity = a / (1 - r) = 1 / (1 - 1/2) = 1 / (1/2) = 2.',
    'easy', 1, 0, 16, ARRAY['BCA-105N', 'Unit-2', 'GP', 'Infinite-Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

