    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If three positive numbers a, b, c are in GP, which relationship holds true?', 'In GP, the ratio b/a = c/b, which cross-multiplies to b^2 = ac.',
