  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'A sequence of non-zero numbers is in Harmonic Progression (HP) if and only if:', 'By definition, a sequence t1, t2, t3, ... is in HP if 1/t1, 1/t2, 1/t3, ... forms an AP.',
    'easy', 1, 0, 21, ARRAY['BCA-105N', 'Unit-2', 'HP', 'Definition']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

