  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Harmonic Mean between 3 and 6?', 'HM = 2 * 3 * 6 / (3 + 6) = 36 / 9 = 4.',
    'easy', 1, 0, 23, ARRAY['BCA-105N', 'Unit-2', 'HM', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
