  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'For any two distinct positive real numbers a and b, the strict inequality connecting their AM, GM, and HM is:', 'For distinct positive numbers, the inequality chain is strictly AM > GM > HM (and AM = GM = HM if and only if a = b).',
    'easy', 1, 0, 24, ARRAY['BCA-105N', 'Unit-2', 'Means-Relation', 'Inequality']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
