  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the fundamental algebraic relationship connecting the Arithmetic Mean (A), Geometric Mean (G), and Harmonic Mean (H) of two positive numbers?', 'Proof: A * H = [(a+b)/2] * [2ab/(a+b)] = ab = (sqrt(ab))^2 = G^2.',
    'easy', 1, 0, 25, ARRAY['BCA-105N', 'Unit-2', 'Means-Relation', 'G2-equals-AH']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
