    (v_q_id, 'H^2 = A * G', false, 3, now(), now()),
    (v_q_id, 'A + H = 2G', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If the AM of two numbers is 9 and their HM is 4, what is their GM?', 'G^2 = A * H = 9 * 4 = 36 -> G = sqrt(36) = 6.',
    'easy', 1, 0, 26, ARRAY['BCA-105N', 'Unit-2', 'Means-Relation', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

