  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If AM = GM for two positive numbers a and b, what can be concluded?', 'AM = GM implies (a + b)/2 = sqrt(ab) -> (sqrt(a) - sqrt(b))^2 = 0 -> a = b.',
    'medium', 1, 0, 27, ARRAY['BCA-105N', 'Unit-2', 'Means-Relation', 'Equality-Condition']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

