  ) VALUES (
    v_quiz_id, 'single', 'What is the 5th term of the HP whose reciprocal AP is 1/2, 1/4, 1/6, 1/8, ...?', 'The 5th term of the AP is 1/2 + 4 * (1/4 - 1/2) ... wait: 2, 4, 6, 8, 10. The AP is 2, 4, 6, 8, 10. Reciprocal HP is 1/2, 1/4, 1/6, 1/8, 1/10.',
    'easy', 1, 0, 28, ARRAY['BCA-105N', 'Unit-2', 'HP', 'nth-Term']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

