  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Can a Harmonic Progression contain the number 0 as one of its terms?', 'Because HP terms are reciprocals of AP terms, zero cannot be a term since 1/0 is mathematically undefined.',
    'medium', 1, 0, 30, ARRAY['BCA-105N', 'Unit-2', 'HP', 'Zero-Constraint']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

