  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the formula for the sum of squares of the first n natural numbers (1^2 + 2^2 + ... + n^2)?', 'The standard summation formula for squares is sum(k^2) = n(n + 1)(2n + 1) / 6.',
    'easy', 1, 0, 31, ARRAY['BCA-105N', 'Unit-2', 'Special-Series', 'Sum-of-Squares']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

