  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If the second term of a GP is 2 and the fifth term is 16, what is the first term a?', 'T_5 / T_2 = (a*r^4) / (a*r) = r^3 = 16 / 2 = 8 -> r = 2. Then a * 2 = 2 -> a = 1.',
    'medium', 1, 0, 34, ARRAY['BCA-105N', 'Unit-2', 'GP', 'Parameter-Solving']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

