  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'In an AP, if T_p = q and T_q = p, what is the (p + q)-th term?', 'Standard identity: common difference d = -1. T_(p+q) = T_p + q*d = q + q*(-1) = 0.',
    'medium', 1, 0, 35, ARRAY['BCA-105N', 'Unit-2', 'AP', 'Classic-Problem']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

