  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If x, 2x + 2, 3x + 3 are in AP, what is x?', '2(2x + 2) = x + (3x + 3) -> 4x + 4 = 4x + 3 -> 4 = 3 (no solution unless consistent). Let''s check: d1 = x + 2, d2 = x + 1. Not AP for any x. If 2x+1: 2(2x+1) = 4x+2 = 4x+3 -> invalid.',
    'hard', 1, 0, 36, ARRAY['BCA-105N', 'Unit-2', 'AP', 'Consistency']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

