  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the sum of the series 5 + 55 + 555 + ... to n terms?', 'Standard method: 5/9 * (9 + 99 + 999 + ...) = (5/9) * sum(10^k - 1) = (5/9)[(10/9)(10^n - 1) - n].',
    'medium', 1, 0, 37, ARRAY['BCA-105N', 'Unit-2', 'Special-Series', 'Repunit-Sum']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

