  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'The geometric mean of 3, 9, 27 is:', 'GM of 3 numbers = (3 * 9 * 27)^(1/3) = (3^1 * 3^2 * 3^3)^(1/3) = (3^6)^(1/3) = 3^2 = 9.',
    'medium', 1, 0, 38, ARRAY['BCA-105N', 'Unit-2', 'GM', 'Multiple-Numbers']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

