    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If a, b, c are in AP, then 2^a, 2^b, 2^c are in:', 'Since b - a = c - b = d, 2^b / 2^a = 2^(b-a) = 2^d and 2^c / 2^b = 2^d (constant ratio). Hence they form a GP.',
    'medium', 1, 0, 39, ARRAY['BCA-105N', 'Unit-2', 'Progressions', 'Transformation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

