  ) VALUES (
    v_quiz_id, 'single', 'The n-th term from the end of an AP having last term ''l'' and common difference ''d'' is given by:', 'Starting from the end, the first term is l and common difference is -d; thus T''_n = l + (n - 1)(-d) = l - (n - 1)d.',
    'medium', 1, 0, 41, ARRAY['BCA-105N', 'Unit-2', 'AP', 'Term-From-End']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

