  ) VALUES (
    v_quiz_id, 'single', 'Under what condition does an infinite Geometric Progression (GP) converge to a finite sum?', 'An infinite GP converges if and only if |r| < 1, with sum S_infinity = a / (1 - r).',
    'easy', 1, 0, 45, ARRAY['BCA-105N', 'Unit-2', 'GP', 'Convergence']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

