  ) VALUES (
    v_quiz_id, 'single', 'What is the sum of the infinite geometric series: 1 + 1/2 + 1/4 + 1/8 + ...?', 'Here a = 1, r = 1/2 < 1. S_infinity = a / (1 - r) = 1 / (1 - 0.5) = 2.',
    'easy', 1, 0, 46, ARRAY['BCA-105N', 'Unit-2', 'GP', 'Infinite-Sum']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

