  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the mathematical relation between the Arithmetic Mean (A), Geometric Mean (G), and Harmonic Mean (H) of two positive numbers?', 'A = (a+b)/2, G = sqrt(ab), H = 2ab/(a+b). A * H = [(a+b)/2] * [2ab/(a+b)] = ab = G^2.',
    'medium', 1, 0, 50, ARRAY['BCA-105N', 'Unit-2', 'Means', 'Relation']::TEXT[], 2024, 'MJPRU BCA Sem 1',
    now(), now()
  ) RETURNING id INTO v_q_id;

